# Convert the string to a list of lists
embeddings = []
for line in embeddings_string.strip().split("\n"):
    embeddings.append([float(x) for x in line.strip()[1:-1].split(",")])

# Convert the list to a NumPy array
embeddings_array = np.array(embeddings)

# Perform PCA to reduce dimensionality to 3D
pca = PCA(n_components=3)
embeddings_3d = pca.fit_transform(embeddings_array)

# Perform DBSCAN clustering
dbscan = DBSCAN(eps=0.3, min_samples=2)
labels = dbscan.fit_predict(embeddings_3d)

# Re-label clusters based on path connectivity
new_labels = np.full(labels.shape, -1)
current_cluster = 0
noise_label = -1

for i in range(len(labels)):
    if new_labels[i] == -1:  # If not yet labeled
        if labels[i] == -1:
            new_labels[i] = noise_label  # Keep noise points labeled as -1
        else:
            current_label = labels[i]
            for j in range(i, len(labels)):
                if labels[j] == current_label and (j == i or labels[j-1] == current_label):
                    new_labels[j] = current_cluster
                else:
                    break
            current_cluster += 1

# Plot the 3D embeddings with clusters
fig = plt.figure(figsize=(10, 8))
ax = fig.add_subplot(111, projection='3d')

# Define more discrete colors for clusters
colors = [
    'r', 'g', 'b', 'c', 'm', 'y', 'k', 'orange', 'purple', 'pink', 'brown', 'grey', 'olive', 'cyan', 'magenta',
    'navy', 'teal', 'coral', 'gold', 'lime', 'salmon', 'plum', 'orchid', 'sienna', 'lavender', 'khaki', 'ivory'
]

# Plot each point with its cluster label
unique_labels = set(new_labels)
for label in unique_labels:
    class_member_mask = (new_labels == label)
    xyz = embeddings_3d[class_member_mask]
    if label == -1:
        # Noise points
        ax.plot(xyz[:, 0], xyz[:, 1], xyz[:, 2], 'o', markerfacecolor='k', markeredgecolor='k', markersize=6)
    else:
        color = colors[label % len(colors)]  # Cycle through the defined colors
        ax.plot(xyz[:, 0], xyz[:, 1], xyz[:, 2], 'o', markerfacecolor=color, markeredgecolor='k', markersize=10)

# Plot lines between points in order
ax.plot(embeddings_3d[:, 0], embeddings_3d[:, 1], embeddings_3d[:, 2], linestyle='-', color='blue')

# Label each point with the first word of the corresponding text string
for i, txt in enumerate(texts):
    # if i % 10 == 0:
    first_word = txt.split()[0]
    ax.text(embeddings_3d[i, 0], embeddings_3d[i, 1], embeddings_3d[i, 2], first_word)


ax.set_title('3D PCA of Embeddings with Path Connectivity Clusters and Connecting Lines')
ax.set_xlabel('Principal Component 1')
ax.set_ylabel('Principal Component 2')
ax.set_zlabel('Principal Component 3')
plt.show()
